from solver import parse_duration
cases = {'1h30m': 5400000, ' .25s ': 250, '1ms2ms': 3, '1.1ms': 2, '0s': 0, '1 s': 1000}
for text, want in cases.items():
    got = parse_duration(text)
    assert got == want, (text, got, want)
for text in ['', '   ', '+1s', '-1s', '1.s', '.s', '1S', '1xs', '1 s2m', '1.2.3s', '1\u00a0s', '1e3s']:
    try:
        parse_duration(text)
    except ValueError:
        pass
    else:
        raise AssertionError(f'accepted invalid: {text!r}')
try:
    parse_duration(None)
except ValueError:
    pass
else:
    raise AssertionError('accepted non-string')
print('boundary checks passed')
